/// <summary>
/// CB166_SalesOrderSubstitutes
/// </summary>
[DataContractAttribute]
class METPostSalesOrderCreationProcessingContract extends METSysOperationTaskDataContract
{
    METExcludeLinesWithManualReservation excludeLines;
    str packedQuery;
    guid topPickingProcessId;

}

Method.Source:
    /// <summary>
    /// get/set the top picking process guid id
    /// </summary>
    /// <param name = "_topPickingProcessId">Top picking process guid id</param>
    /// <returns>Top picking process guid id</returns>
    [DataMember, SysOperationControlVisibilityAttribute(false)]
    public guid parmTopPickingProcessId(guid _topPickingProcessId = topPickingProcessId)
    {
        topPickingProcessId = _topPickingProcessId;

        return topPickingProcessId;
    }

    [
        DataMemberAttribute,
        AifQueryTypeAttribute('_packedQuery', queryStr(METPostSalesOrderCreationProcessingQuery))
    ]
    public str parmPackedQuery(str _packedQuery = packedQuery)
    {
        packedQuery = _packedQuery;

        return packedQuery;
    }

/// <summary>
/// Method to get query object from packedQuery
/// </summary>
/// <returns><c>Query</c> object from packedQuery</returns>
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}

    /// <summary>
    /// Determines whether the parameters are valid.
    /// </summary>
    /// <returns>
    /// true when the parameters are valid; otherwise, false.
    /// </returns>
    public boolean validate()
    {
        boolean isValid = super();
        Query query;
        QueryBuildDataSource qbdsMETSalesTable;
        QueryBuildRange      qbr;
        str orderProcessingStatusFilter;

        // Need to validate below ranges are set
        if (isValid && packedQuery)
        {
            query = this.getQuery();

            qbdsMETSalesTable = query.dataSourceTable(tableNum(METSalesTable));

            qbr = qbdsMETSalesTable.findRange(fieldNum(METSalesTable, OrderProcessingStatus));

            if (qbr)
            {
                orderProcessingStatusFilter = qbr.value();

                // if no order processing status range value
                if (!orderProcessingStatusFilter)
                {
                    isValid = checkFailed(strFmt("@SYS84753", fieldId2PName(tableNum(METSalesTable), fieldNum(METSalesTable, OrderProcessingStatus))));
                }     
            }
            else
            {
                // Check if the range was recreated against SalesTable
                str statement = query.dataSourceTable(tableNum(SalesTable)).toString();

                int orderProcessingStatusPos = strScan(statement, METConstants::orderProcessingStatusEqual, 1, strLen(statement));

                if (!orderProcessingStatusPos)
                {
                    isValid = checkFailed(strFmt("@SYS84753", fieldId2PName(tableNum(METSalesTable), fieldNum(METSalesTable, OrderProcessingStatus))));
                }
            }
        }
        
        return isValid;
    }
